    "source": "/*  This class is used to consolidate some of the actions by the Transaction registry and other pages. */\n\nclass GenericUIController\n   method checkAppClass(&pkgName As string, &applClass As string) Returns boolean;\nend-class;\n\n\nmethod checkAppClass\n   /+ &pkgName as String, +/\n   /+ &applClass as String +/\n   /+ Returns Boolean +/\n   If (None(&pkgName)) Then\n      Return True;\n   Else\n      If (None(&applClass)) Then\n         Error (MsgGetText(236, 53, \"The Application Class is invalid\"));\n      End-If;\n   End-If;\n   Local string &val;\n   Local SQL &sql = GetSQL(SQL.PTAF_APP_CLASS_CHECK, &pkgName, &applClass);\n   Local boolean &count = &sql.Fetch(&val);\n   \n   If None(&val) Then\n      Error (MsgGetText(236, 53, \"The Application Class is invalid\"));\n   End-If;\n   \n   Return True;\nend-method;\n\n",
